/**
 * Shared type definitions for the simulation engine.
 * This file contains NO React imports — the simulation layer is framework-independent.
 */

import type { SimulationEvent } from "../events/types";

/**
 * Every entity in the simulation is one of these types.
 * Maps to the components users can drag onto the canvas.
 */
export type EntityType =
  | "client"
  | "api"
  | "database"
  | "cache"
  | "load_balancer"
  | "cdn"
  | "message_queue"
  | "rate_limiter"
  | "circuit_breaker"
  | "replica_pool"
  | "reverse_proxy"
  | "kafka"
  | "llm_call"
  | "tool_call"
  | "agent_orchestrator"
  | "memory_context_store"
  | "retriever"
  | "guardrail_validator"
  | "model_router"
  | "human_in_loop_gate";

/**
 * How the simulation clock reports time.
 * All simulation time is in milliseconds (virtual).
 */
export type Timestamp = number;

/**
 * A unique identifier for a request as it flows through the system.
 * Generated by the Client and carried through every event.
 */
export type RequestId = string;

/**
 * A unique identifier for any entity instance in the simulation.
 */
export type EntityId = string;

/**
 * The result of running a simulation.
 * Immutable — produced once, consumed by playback.
 */
export interface SimulationResult {
  events: SimulationEvent[];
  metrics: MetricsSnapshot;
  duration: number; // total simulated time in ms
  warnings: string[];
  errors: string[];
  metadata: SimulationMetadata;
  /** Ids of Client entities in this run — see MetricsCollector's clientIds param. */
  clientIds: EntityId[];
  /** Ids of Agent Orchestrator entities in this run — see MetricsCollector's agentOrchestratorIds param (Phase 5, docs/Agentic_AI.md §2.5). */
  agentOrchestratorIds: EntityId[];
  /** Ids of Guardrail Validator entities in this run — see MetricsCollector's guardrailValidatorIds param (Phase 5, docs/Agentic_AI.md §2.5). */
  guardrailValidatorIds: EntityId[];
}

/**
 * Metrics snapshot — a point-in-time capture of all metrics.
 * All metrics derive from the event timeline.
 */
export interface MetricsSnapshot {
  // Aggregate
  totalRequests: number;
  successfulRequests: number;
  failedRequests: number;
  successRate: number; // 0.0 - 1.0

  // Latency (ms)
  averageLatency: number;
  p50Latency: number;
  p95Latency: number;
  p99Latency: number;

  // Throughput (requests per second of simulation time)
  throughput: number;

  // Per-entity metrics
  entityMetrics: Record<EntityId, EntityMetrics>;

  /**
   * `docs/Agentic_AI.md` §2.5's loop/iteration count — surfaces failure
   * modes #5 (infinite retry loop) and #6 (agent paralysis) directly in
   * the metrics panel, without inspecting individual entities. Sum, across
   * every Agent Orchestrator in this run, of "dispatches beyond the
   * first" per session (a session's own admission accounts for one; every
   * dispatch past that is a retry or a fan-out worker). A healthy
   * architecture with no orchestrator, or one whose orchestrators only
   * ever dispatch once per session, reads 0 — this only grows when a
   * session genuinely retried or fanned out. `undefined` when this run
   * has no Agent Orchestrator entities at all, same "absent means not
   * applicable" convention `cacheHitRate`/`memoryContext`/etc. already use.
   */
  totalIterations?: number;

  /**
   * `docs/Agentic_AI.md` §2.5's guardrail rejection rate — aggregate
   * rejections / total checks across every Guardrail Validator entity in
   * this run (gate rejections, scorer threshold misses, and caught
   * compromises all count as rejections; a check is every attempt the
   * validator actually ran, pass or fail). `undefined` when this run has
   * no Guardrail Validator entities.
   */
  guardrailRejectionRate?: number;
}

export interface EntityMetrics {
  utilization: number; // 0.0 - 1.0
  requestCount: number;
  errorCount: number;
  queueLength: number;
  /** Only present for entities that emit CACHE_HIT/CACHE_MISS (Cache, CDN). */
  cacheHitRate?: number; // 0.0 - 1.0
  /** Only present for entities whose CACHE_HIT/CACHE_MISS events carry an edgeIndex (CDN). */
  cdnEdges?: CDNEdgeMetrics[];
  /** Only present for load balancers — how many requests each downstream target received. */
  routingDistribution?: RoutingTargetMetrics[];
  /** Only present for rate limiters. */
  rateLimiter?: RateLimiterMetrics;
  /** Only present for circuit breakers. */
  circuitBreaker?: CircuitBreakerMetrics;
  /** Only present for caches that saw at least one miss — see Cache.ts's stampedeMode. */
  cacheStampede?: CacheStampedeMetrics;
  /** Only present for caches that saw at least one miss for a nonexistent key — see Cache.ts's negativeCaching. */
  cachePenetration?: CachePenetrationMetrics;
  /** Only present for caches that saw at least one TTL-expiry-driven miss — see Cache.ts's ttlJitterPercent. */
  cacheAvalanche?: CacheAvalancheMetrics;
  /** Only present for Kafka — how many messages hashed to each partition. Reuses RoutingTargetMetrics' shape (targetId holds a synthetic "Partition N" label, not a real entity id). */
  kafkaPartitions?: RoutingTargetMetrics[];
  /** Only present for a MemoryContextStore that compacted at least once. */
  memoryContext?: MemoryContextMetrics;
}

export interface RoutingTargetMetrics {
  targetId: EntityId;
  requests: number;
}

export interface RateLimiterMetrics {
  admitted: number;
  rejected: number;
}

export interface CacheStampedeMetrics {
  /** Misses that found another fetch for the same key already in flight and waited on it instead of fetching independently — only possible under stampedeMode "coalesced". */
  coalescedMisses: number;
  /** Misses that each triggered their own independent downstream fetch. */
  independentMisses: number;
}

export interface CachePenetrationMetrics {
  /** Misses for a key confirmed nonexistent, answered directly from a negative-cache entry — no downstream trip. Only possible under negativeCaching "on". */
  negativeHits: number;
  /** Misses for a key confirmed nonexistent that still reached downstream — the naive default, or a negative-cache entry that hadn't been written yet. */
  downstreamMisses: number;
}

export interface CacheAvalancheMetrics {
  /** Misses caused by a previously-cached entry's own TTL expiring, as opposed to a key that was simply never cached (or was evicted for capacity). */
  expiredMisses: number;
  /** The largest number of expiry-driven misses that landed within a 100ms window of each other, anywhere in the run — the quantified size of an avalanche's "wave". */
  peakExpiryBurst: number;
}

/**
 * Derived from CONTEXT_COMPACTED events — see MemoryContextStore.ts.
 * `criticalInfoIntact` is "last one wins" across compactions (same
 * point-in-time reasoning CircuitBreakerMetrics.state uses), so it
 * reflects whether the session's original critical info has survived as
 * of the most recent compaction, not just the first.
 */
export interface MemoryContextMetrics {
  policy: "none" | "summarization" | "scratchpad";
  compactionCount: number;
  criticalInfoIntact: boolean;
  /** Context size, in tokens, immediately after the most recent compaction. */
  currentContextTokens: number;
}

export type CircuitBreakerState = "closed" | "open" | "half_open";

export interface CircuitBreakerMetrics {
  state: CircuitBreakerState;
  tripCount: number;
}

export interface CDNEdgeMetrics {
  edgeIndex: number;
  hitRate: number; // 0.0 - 1.0
  requests: number; // hits + misses seen at this edge
  misses: number; // subset of requests that fell through to the origin
}

/**
 * Result of running the same architecture twice — once as-is, once with
 * one entity spliced out (see compareArchitectures.ts) — to show its
 * real, measured effect rather than asserting it.
 */
export interface ArchitectureComparison {
  withAverageLatency: number;
  withoutAverageLatency: number;
  withSuccessRate: number;
  withoutSuccessRate: number;
}

/**
 * Simulation metadata — info about the run itself.
 */
export interface SimulationMetadata {
  seed: number;
  version: string;
  generatedAt: string;
}

/**
 * Configuration for a simulation run, derived from the user's architecture.
 * This is the shape the workshop-bridge.ts converts canvas state into.
 */
export interface SimulationConfig {
  entities: EntityConfig[];
  connections: ConnectionConfig[];
  scenario: ScenarioDefinition;
  options: SimulationOptions;
}

export interface EntityConfig {
  id: EntityId;
  type: EntityType;
  position: { x: number; y: number };
  config: Record<string, unknown>;
}

export interface ConnectionConfig {
  source: EntityId;
  target: EntityId;
  latencyMs?: number;
  protocol?: string;
}

export interface ScenarioDefinition {
  id: string;
  title: string;
  trafficPattern: TrafficPattern;
  durationMs: number;
  failureEvents?: FailureEvent[];
}

export type TrafficPattern =
  | { type: "constant"; rate: number }
  | { type: "burst"; rate: number; interval: number; duration: number }
  | { type: "ramp"; startRate: number; endRate: number; duration: number };

export interface FailureEvent {
  timestamp: Timestamp;
  entityId: EntityId;
  failureType: string;
  durationMs?: number;
}

export interface SimulationOptions {
  seed: number;
  maxSteps?: number; // safety limit for runaway simulations
}
